using System.Collections.Generic;using LWS.TruckSports;using UnityEngine;
namespace LWS.TruckTeaParty {
 // Physical articulated machinery extends the existing Egg&Spoon kinematic
 // tool foundation. It never moves a truck or teleports a carried object.
 public sealed class ServingArm:MonoBehaviour {
  public SportsEventTruck truck;public Transform gear;public Rigidbody shoulder,elbow,grip;public Collider[] contacts;public Vector3 mount=new Vector3(0,2,2.5f);public float clock;public ServingVessel Held{get;private set;}public Vector3 WorldGoal{get;private set;}public float Tilt{get;private set;}public int NativeCandidates{get;private set;}
  struct OwnPair {public Collider equipment,hull;public bool ignored;}
  readonly List<OwnPair> ownPairs=new List<OwnPair>(128);readonly HashSet<(Collider,Collider)> knownOwnPairs=new HashSet<(Collider,Collider)>();public int IsolatedOwnPairs=>ownPairs.Count;
  // Independent kinematic machinery must not push the original dynamic hull
  // which carries it. Only this gear and this same complete NWH assembly are
  // paired; world, cargo and other participants retain their native contacts.
  public void RefreshOwnCollisionIsolation(){if(gear==null||truck==null)return;contacts=truck.GetComponentsInChildren<Collider>(true);var equipment=gear.GetComponentsInChildren<Collider>(true);foreach(var tool in equipment)foreach(var hull in contacts){if(tool==null||hull==null||hull.transform.IsChildOf(gear)||tool==hull)continue;var key=(tool,hull);if(knownOwnPairs.Add(key))ownPairs.Add(new OwnPair{equipment=tool,hull=hull,ignored=Physics.GetIgnoreCollision(tool,hull)});Physics.IgnoreCollision(tool,hull,true);}}
  void OnDestroy(){foreach(var pair in ownPairs)if(pair.equipment!=null&&pair.hull!=null)Physics.IgnoreCollision(pair.equipment,pair.hull,pair.ignored);}
  readonly Dictionary<ServingVessel,float> candidates=new Dictionary<ServingVessel,float>(12);Rigidbody[] secondary;bool[] originalKinematic;bool cached;float yaw,height=2.5f;Vector3 previousBase,pourDirection=Vector3.forward;
  public void Observe(ServingVessel vessel){if(vessel.Broken||vessel.Banked||vessel.Holder!=null)return;if(!candidates.ContainsKey(vessel))NativeCandidates++;candidates[vessel]=clock;}
  void Cache(){if(cached)return;cached=true;var all=truck.GetComponentsInChildren<Rigidbody>(true);secondary=System.Array.FindAll(all,b=>b!=truck.body);originalKinematic=new bool[secondary.Length];for(int i=0;i<secondary.Length;i++)originalKinematic[i]=secondary[i].isKinematic;}
  public void Prepare(Vector3 p,Quaternion rotation){Cache();Drop();candidates.Clear();NativeCandidates=0;yaw=0;height=2.5f;Tilt=0;truck.tractorMotor.Configure();truck.Prepare(p,rotation);for(int i=0;i<secondary.Length;i++)secondary[i].isKinematic=originalKinematic[i];RefreshOwnCollisionIsolation();WorldGoal=truck.transform.TransformPoint(new Vector3(0,height,7));Move(WorldGoal,0,true);}
  public bool Grab(){if(Held!=null||!truck.session.Live)return false;ServingVessel best=null;float distance=9;foreach(var pair in candidates){var v=pair.Key;if(v==null||!v.PickupAllowed||v.Broken||v.Banked||v.Holder!=null||clock-pair.Value>.15f)continue;float d=(v.body.position-grip.position).sqrMagnitude;if(d<distance){best=v;distance=d;}}if(best==null||!best.Attach(this))return false;Held=best;pourDirection=best.spout!=null?Quaternion.Inverse(grip.rotation)*Vector3.ProjectOnPlane(best.spout.forward,Vector3.up).normalized:Vector3.forward;return true;}
  public void Released(ServingVessel vessel){if(Held==vessel)Held=null;}
  public void Drop(){if(Held!=null)Held.Drop();Held=null;}
  public void Manual(Vector2 axes,bool adjust,bool pour,float dt){if(adjust){yaw=Mathf.Clamp(yaw+axes.x*30*dt,-55,55);height=Mathf.Clamp(height+axes.y*1.5f*dt,.7f,5.2f);}var local=Quaternion.Euler(0,yaw,0)*new Vector3(0,height,7);Move(truck.transform.TransformPoint(local),pour?62:0,false,dt);}
  public void Move(Vector3 goal,float tilt,bool snap=false,float dt=.02f){var basePoint=truck.transform.TransformPoint(mount);goal=basePoint+Vector3.ClampMagnitude(goal-basePoint,8);if(!snap)WorldGoal+=basePoint-previousBase;previousBase=basePoint;WorldGoal=snap?goal:basePoint+Vector3.ClampMagnitude(Vector3.MoveTowards(WorldGoal,goal,dt*2.2f)-basePoint,8);Tilt=snap?tilt:Mathf.MoveTowards(Tilt,tilt,dt*40);var bend=(basePoint+WorldGoal)*.5f+truck.transform.up*1.6f;SetLink(shoulder,basePoint,bend,snap);SetLink(elbow,bend,WorldGoal,snap);var neutral=truck.body.rotation*Quaternion.Euler(0,yaw,0);var forward=Vector3.ProjectOnPlane(neutral*pourDirection,Vector3.up).normalized;if(forward.sqrMagnitude<.01f)forward=truck.transform.forward;var rotation=Quaternion.AngleAxis(Tilt,Vector3.Cross(Vector3.up,forward))*neutral;if(snap){grip.position=WorldGoal;grip.rotation=rotation;grip.transform.SetPositionAndRotation(WorldGoal,rotation);}else{grip.MovePosition(WorldGoal);grip.MoveRotation(rotation);}}
  static void SetLink(Rigidbody body,Vector3 a,Vector3 b,bool snap){var position=(a+b)*.5f;var rotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);body.transform.localScale=new Vector3(.35f,Mathf.Max(.1f,(b-a).magnitude),.35f);if(snap){body.position=position;body.rotation=rotation;body.transform.SetPositionAndRotation(position,rotation);}else{body.MovePosition(position);body.MoveRotation(rotation);}}
  public void Freeze(){Cache();Drop();truck.Power(false);if(!truck.body.isKinematic)truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;foreach(var body in secondary){if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.isKinematic=true;}shoulder.isKinematic=elbow.isKinematic=grip.isKinematic=true;}
 }
}
